        // ==========================================================
        // Generate PDF Report
        // ==========================================================

        public async Task<ReportOutputDTO> GenerateReportAsync(ReportInputDTO dto)
        {
            // مجلد حفظ التقارير
            var reportsFolder = Path.Combine(
                Directory.GetCurrentDirectory(),
                "wwwroot",
                "reports"
            );

            // إنشاء المجلد إذا لم يكن موجوداً
            Directory.CreateDirectory(reportsFolder);

            var generatedAt = DateTime.Now;

            // اسم فريد للملف
            var fileName =
                $"trainer-report-{dto.TrainerId ?? 0}-{generatedAt:yyyyMMddHHmmssfff}.pdf";

            var fullPath = Path.Combine(reportsFolder, fileName);

            // ======================================================
            // جلب مؤشرات المدرب
            // ======================================================

            TrainerKpisDTO? kpis = null;

            if (dto.TrainerId.HasValue)
            {
                kpis = await _repository.GetTrainerKpisAsync(
                    dto.TrainerId.Value
                );
            }

            // ======================================================
            // إنشاء ملف PDF
            // ======================================================

            var document = Document.Create(container =>
            {
                container.Page(page =>
                {
                    page.Size(PageSizes.A4);

                    page.Margin(30);

                    page.DefaultTextStyle(style =>
                        style.FontSize(12)
                    );

                    // ---------------- Header ----------------

                    page.Header()
                        .AlignCenter()
                        .Text("تقرير المدرب")
                        .FontSize(22)
                        .Bold();

                    // ---------------- Content ----------------

                    page.Content()
                        .PaddingVertical(20)
                        .Column(column =>
                        {
                            column.Spacing(12);

                            column.Item()
                                .AlignRight()
                                .Text($"نوع التقرير: {dto.Type}");

                            if (dto.TrainerId.HasValue)
                            {
                                column.Item()
                                    .AlignRight()
                                    .Text(
                                        $"رقم المدرب: {dto.TrainerId.Value}"
                                    );
                            }

                            column.Item()
                                .AlignRight()
                                .Text(
                                    $"تاريخ الإنشاء: {generatedAt:yyyy-MM-dd HH:mm}"
                                );

                            // ----------------------------------
                            // KPIs
                            // ----------------------------------

                            if (kpis != null)
                            {
                                column.Item()
                                    .PaddingTop(15)
                                    .AlignRight()
                                    .Text("مؤشرات الأداء")
                                    .FontSize(17)
                                    .Bold();

                                column.Item()
                                    .AlignRight()
                                    .Text(
                                        $"نسبة الحضور العامة: {kpis.AttendanceRate}%"
                                    );

                                column.Item()
                                    .AlignRight()
                                    .Text(
                                        $"معدل إنجاز المهام: {kpis.TaskCompletionRate}%"
                                    );

                                column.Item()
                                    .AlignRight()
                                    .Text(
                                        $"متوسط الدرجات الفنية: {kpis.AvgTechnicalGrade} / 100"
                                    );
                            }

                            // ----------------------------------
                            // Filters
                            // ----------------------------------

                            if (!string.IsNullOrWhiteSpace(dto.FiltersJson))
                            {
                                column.Item()
                                    .PaddingTop(15)
                                    .AlignRight()
                                    .Text("بيانات التقرير")
                                    .FontSize(15)
                                    .Bold();

                                column.Item()
                                    .AlignRight()
                                    .Text(dto.FiltersJson);
                            }
                        });

                    // ---------------- Footer ----------------

                    page.Footer()
                        .AlignCenter()
                        .Text(text =>
                        {
                            text.Span("بوابة نفاذ - ");
                            text.Span("تقرير المدرب");
                        });
                });
            });

            // حفظ PDF داخل wwwroot/reports
            document.GeneratePdf(fullPath);

            // نخزن المسار النسبي فقط في قاعدة البيانات
            var fileUrl = $"reports/{fileName}";

            // ======================================================
            // حفظ سجل التقرير في قاعدة البيانات
            // ======================================================

            var report = new NFD_Report
            {
                Type = dto.Type,
                FiltersJson = dto.FiltersJson,
                GeneratedAt = generatedAt,
                FileUrl = fileUrl,
                GeneratedByUserId = dto.GeneratedByUserId
            };

            await _repository.AddReportAsync(report);

            // ======================================================
            // Return
            // ======================================================

            return new ReportOutputDTO
            {
                ReportId = report.ReportId,
                Type = report.Type,
                FiltersJson = report.FiltersJson,
                GeneratedAt = report.GeneratedAt,
                FileUrl = report.FileUrl,
                GeneratedByUserId = report.GeneratedByUserId
            };
        }

        // ==========================================================
        // Generate Trainer Trainees PDF Report
        // ==========================================================

        public async Task<ReportOutputDTO> GenerateTrainerTraineesReportAsync(
            TrainerTraineesReportInputDto dto
        )
        {
            // ======================================================
            // Get trainee rows
            // ======================================================

            var rows =
                await _repository.GetTrainerTraineesReportRowsAsync(
                    dto.TrainerId,
                    dto.BatchId
                );


            // ======================================================
            // Reports folder
            // ======================================================

            var reportsFolder = Path.Combine(
               @"C:\NafadhStorage",
               "Reports"


            );

            Directory.CreateDirectory(reportsFolder);


            var generatedAt = DateTime.Now;


            var fileName =
                $"trainer-trainees-{dto.TrainerId}-{generatedAt:yyyyMMddHHmmssfff}.pdf";


            var fullPath =
                Path.Combine(
                    reportsFolder,
                    fileName
                );


            // ======================================================
            // Generate PDF
            // ======================================================

            var document =
                Document.Create(container =>
                {
                    container.Page(page =>
                    {
                        page.Size(
                            PageSizes.A4.Landscape()
                        );

                        page.Margin(30);


                        page.DefaultTextStyle(
                            style =>
                                style.FontSize(10)
                        );


                        // ------------------------------------------
                        // Header
                        // ------------------------------------------

                        page.Header()
                            .Column(header =>
                            {
                                header.Item()
                                    .AlignCenter()
                                    .Text("كشف تقييم ومتابعة المتدربين")
                                    .FontSize(20)
                                    .Bold();


                                header.Item()
                                    .PaddingTop(6)
                                    .AlignCenter()
                                    .Text(
                                        $"رقم المدرب: {dto.TrainerId}"
                                    )
