                                    .PaddingTop(3)
                                    .AlignCenter()
                                    .Text(
                                        $"تاريخ التصدير: {generatedAt:yyyy-MM-dd HH:mm}"
                                    )
                                    .FontSize(10);
                            });


                        // ------------------------------------------
                        // Content
                        // ------------------------------------------

                        page.Content()
                            .PaddingVertical(20)
                            .Column(column =>
                            {
                                column.Spacing(10);


                                if (rows.Count == 0)
                                {
                                    column.Item()
