                    report.Type,

                FiltersJson =
                    report.FiltersJson,

                GeneratedAt =
                    report.GeneratedAt,

                FileUrl =
                    report.FileUrl,

                GeneratedByUserId =
                    report.GeneratedByUserId
            };
        }

        // ==========================================================
        // GET Report/{id}
        // ==========================================================

        public async Task<ReportOutputDTO?> GetReportByIdAsync(int reportId)
        {
            var report = await _repository.GetReportByIdAsync(reportId);

            if (report == null)
                return null;

            return new ReportOutputDTO
            {
                ReportId = report.ReportId,
                Type = report.Type,
                FiltersJson = report.FiltersJson,
                GeneratedAt = report.GeneratedAt,
                FileUrl = report.FileUrl,
                GeneratedByUserId = report.GeneratedByUserId
            };
        }

        // ==========================================================
        // GET Report/{id}/download
        // ==========================================================

        public async Task<string?> DownloadReportAsync(int reportId)
        {
            var report = await _repository.GetReportByIdAsync(reportId);

            if (report == null)
                return null;

            return report.FileUrl;
        }
        // ==========================================================
        // Trainer Portal Report File
        // ==========================================================

        // Resolves Trainer Portal reports only from the configured
        // external reports folder without affecting shared reports.
        public async Task<string?>
            GetTrainerPortalReportFilePathAsync(
                int reportId
            )
        {
            var report =
                await GetReportByIdAsync(
                    reportId
                );


            if (
                report == null ||
                string.IsNullOrWhiteSpace(
                    report.FileUrl
                )
            )
            {
                return null;
            }


            var reportsFolder =
                _configuration[
                    "Storage:TrainerReportsPath"
                ];


            if (
                string.IsNullOrWhiteSpace(
                    reportsFolder
                )
            )
            {
                return null;
            }


            var reportsRoot =
                Path.GetFullPath(
                    reportsFolder
                );


            var filePath =
                Path.GetFullPath(
                    report.FileUrl
                );


            var rootWithSeparator =
                reportsRoot.TrimEnd(
                    Path.DirectorySeparatorChar,
                    Path.AltDirectorySeparatorChar
                )
                + Path.DirectorySeparatorChar;


            // Prevent reading files outside the configured
            // Trainer Portal reports directory.
            if (
                !filePath.StartsWith(
                    rootWithSeparator,
                    StringComparison.OrdinalIgnoreCase
                )
            )
            {
                return null;
            }


            // Keep this endpoint isolated to Trainer Portal PDFs.
            var fileName =
                Path.GetFileName(
                    filePath
                );


            if (
                !fileName.StartsWith(
                    "trainer-portal-report-",
                    StringComparison.OrdinalIgnoreCase
                )
            )
            {
                return null;
            }


            if (
                !File.Exists(
                    filePath
                )
            )
            {
                return null;
            }


            return filePath;
        }
